declare(strict_types=1); require_once __DIR__.'/../app/bootstrap.php'; require_admin();$pdo=db();$row=$pdo->query('SELECT * FROM company_settings ORDER BY id LIMIT 1')->fetch();if(!$row){$pdo->exec("INSERT INTO company_settings(company_name,currency) VALUES('GPM','AOA')");$row=$pdo->query('SELECT * FROM company_settings ORDER BY id LIMIT 1')->fetch();}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$s=$pdo->prepare('UPDATE company_settings SET company_name=?,nif=?,address=?,city=?,province=?,phone=?,email=?,delivery_fee=? WHERE id=?');$s->execute([trim((string)$_POST['company_name']),trim((string)$_POST['nif'])?:null,trim((string)$_POST['address'])?:null,trim((string)$_POST['city'])?:null,trim((string)$_POST['province'])?:null,trim((string)$_POST['phone'])?:null,trim((string)$_POST['email'])?:null,max(0,(float)$_POST['delivery_fee']),(int)$row['id']]);flash('Dados da empresa guardados.');redirect('company.php');}
layout_start('Dados da empresa');echo '<section class="panel"><h2>Identificação comercial</h2><form method="post">'.csrf_field().'<div class="form-grid">';foreach([['company_name','Nome da empresa'],['nif','NIF da empresa'],['phone','Telefone'],['email','Email'],['city','Cidade'],['province','Província']] as [$key,$label])echo '<div class="field"><label>'.e($label).'</label><input name="'.e($key).'" value="'.e($row[$key]??'').'"'.($key==='company_name'?' required':'').'></div>';echo '</div><div class="field"><label>Endereço</label><textarea name="address" rows="3">'.e($row['address']).'</textarea></div><div class="field"><label>Taxa de entrega padrão (Kz)</label><input type="number" min="0" step="0.01" name="delivery_fee" value="'.e($row['delivery_fee']).'"></div><button>Guardar dados</button></form></section>';layout_end();
